package com.github.nacabaro.vbhelper.chat.lorebook

data class WorldLoreEntry(
    val title: String,
    val keys: List<String>,
    val content: String,
    val priority: Int = 10,
    val reference: ResearchReference? = null
)

object DigimonWorldLore {
    fun entries(languageTag: String): List<WorldLoreEntry> {
        fun text(en: String, pt: String, ja: String) = when {
            languageTag.startsWith("pt", true) -> pt
            languageTag.startsWith("ja", true) -> ja
            else -> en
        }
        fun entry(title: String, keys: List<String>, reference: ResearchReference, en: String, pt: String, ja: String,
                  priority: Int = 10) = WorldLoreEntry(title, keys, text(en, pt, ja), priority, reference)

        return listOf(
            entry("Digital World", listOf("Digital World", "Digiworld", "Mundo Digital", "デジタルワールド"), ResearchSources.overview,
                "A network-built cyber-world with seas, continents, and islands, inhabited by digital life. Multiple servers manage it; its original purpose and the identity of human operators remain unknown. Other worlds and layers have distinct ecosystems and administrators.",
                "Um mundo cibernético construído na rede, com mares, continentes e ilhas, habitado por vida digital. Vários servidores o administram; sua finalidade original e a identidade dos operadores humanos permanecem desconhecidas. Outros mundos e camadas têm ecossistemas e administradores próprios.",
                "ネットワーク上の電脳世界で、海、大陸、島々とデジタル生命が存在する。複数のサーバーが管理するが、創造の目的や人間の運営者は不明。他の世界やレイヤーには独自の生態系と管理者がある。", 12),
            entry("Digital life", listOf("Digimon", "digital life", "vida digital", "デジモン"), ResearchSources.overview,
                "Digimon hatch from Digitama, obtain energy from food and data, grow through evolution, and can suffer illness, injury, or death. They do not have reproductive sexes. General ecological descriptions do not determine an individual's personality, history, or identity.",
                "Digimon nascem de Digitama, obtêm energia de alimento e dados, crescem por evolução e podem adoecer, se ferir ou morrer. Não possuem sexos reprodutivos. Descrições gerais de ecologia não determinam a personalidade, a história ou a identidade de um indivíduo.",
                "デジモンはデジタマから生まれ、食物やデータをエネルギーにし、進化で成長する。病気、けが、死も起こる。生殖上の性別はない。一般的な生態だけで個体の性格、来歴、身分は決まらない。", 7),
            entry("Species records", listOf("species", "profile", "espécie", "perfil", "種族", "プロフィール"), ResearchSources.profile(9, "Species and individual records"),
                "A species name identifies a kind of Digimon, not a unique individual. Research records distinguish level, type, attribute, special moves, and profile. A nickname and recorded life belong to the individual; a known species does not prove a particular character identity.",
                "O nome da espécie identifica um tipo de Digimon, não um indivíduo único. A pesquisa distingue nível, tipo, atributo, golpes especiais e perfil. O apelido e a vida registrada pertencem ao indivíduo; uma espécie conhecida não prova a identidade de um personagem específico.",
                "種族名は個体名ではない。研究記録はレベル、タイプ、属性、必殺技、プロフィールを区別する。ニックネームと来歴は個体に属し、種族が同じでも特定の人物とは限らない。"),
            entry("Digivolution", listOf("Digivolution", "Digivolve", "evolution", "Digivolução", "evolução", "進化"), ResearchSources.profile(11, "Growth and branching evolution"),
                "Evolution changes a Digimon's structural data as it incorporates other data. Environment, growth, and potential can produce different routes even within one species. Most stop at Champion; higher forms are rarer. Armor and Hybrid are distinct categories, and device or combat tiers are separate measurements.",
                "A evolução altera os dados estruturais do Digimon ao incorporar outros dados. Ambiente, crescimento e potencial podem produzir rotas diferentes na mesma espécie. Muitos param no nível Adulto; formas superiores são mais raras. Armor e Hybrid são categorias distintas, e os estágios do dispositivo ou de combate são medidas separadas.",
                "進化は他のデータを取り込み構造情報が大きく変わる現象。同じ種族でも環境、育ち、潜在能力により道が分かれる。多くは成熟期で成長が止まり、上位ほど希少。アーマー体、ハイブリッド体と端末・戦闘の段階は区別する。"),
            entry("Attributes", listOf("Vaccine", "Data", "Virus", "Free attribute", "Variable", "atributo", "属性", "ワクチン", "ウィルス"), ResearchSources.profile(20, "Ecological attributes"),
                "Virus tends to change its environment, Vaccine tends to protect or restore it, and Data adapts to it. Free and Variable are separate attributes. Attributes are ecological tendencies, not moral alignment or a complete personality; infancy stages have not developed an attribute.",
                "Virus tende a alterar o ambiente, Vaccine a protegê-lo ou restaurá-lo, e Data a se adaptar. Free e Variable são atributos distintos. São tendências ecológicas, não alinhamentos morais nem personalidades completas; as fases de infância ainda não desenvolveram atributo.",
                "ウィルス種は環境を変え、ワクチン種は守り、データ種は適応する傾向がある。フリーとヴァリアブルも別の属性。善悪や個体の性格を決める分類ではなく、幼年期にはまだ属性が見られない。"),
            entry("Jogress", listOf("Jogress", "DNA evolution", "ジョグレス"), ResearchSources.profile(21, "Jogress and Jogress Evolution"),
                "Jogress combines two Digimon into a new Digimon; the levels need not match or increase. A combination that raises level is Jogress Evolution. Particular pairings can yield particular forms, and changing which partner is the base can change the result. DigiXros and mode changes are distinct processes.",
                "Jogress combina dois Digimon em um novo Digimon; os níveis podem ser diferentes e nem sempre aumentam. Quando o nível sobe, é Jogress Evolution. Certos pares produzem formas específicas, e trocar a base pode mudar o resultado. DigiXros e mudanças de modo são processos distintos.",
                "ジョグレスは二体が合体して新たなデジモンになること。レベルが同じとは限らず、上がるとも限らない。上がる場合はジョグレス進化。組み合わせやベースにより結果が異なる。デジクロスやモードチェンジは区別する。"),
            entry("Digitama", listOf("Digitama", "Digi-Egg", "Digiegg", "デジタマ"), ResearchSources.profile(11, "Digitama and growth"),
                "A Digitama is a Digimon egg. Growth and rebirth are data-life processes, but a battle defeat does not by itself establish death or rebirth. Underworld accounts and the handling of a DigiCore depend on the region and circumstances.",
                "Digitama é o ovo de um Digimon. Crescimento e renascimento são processos de vida digital, mas uma derrota não prova morte ou renascimento. Os relatos sobre o mundo dos mortos e o destino de um DigiCore dependem da região e das circunstâncias.",
                "デジタマはデジモンの卵。成長や再生はデジタル生命の循環だが、バトルの敗北だけで死や再生が確定するわけではない。冥府とデジコアの扱いは地域や状況で異なる。"),
            entry("DigiCore", listOf("DigiCore", "Digi-Core", "デジコア"), ResearchSources.profile(27, "DigiCore and X-Antibody"),
                "The DigiCore is a Digimon's central core. X Program can force it to stop functioning, and X-Antibody can draw out its potential. Storage and transfer are device operations; a copied record does not prove a shared individual identity or shared memories.",
                "DigiCore é o núcleo central de um Digimon. X Program pode interromper seu funcionamento, e X-Antibody pode despertar seu potencial. Armazenamento e transferência são operações de dispositivos; copiar um registro não prova identidade ou lembranças compartilhadas.",
                "デジコアはデジモンの中核。Xプログラムはその機能を停止させ、X抗体は潜在能力を引き出す。端末での保存や転送と、個体の同一性・記憶は区別する。"),
            entry("Yggdrasill", listOf("Yggdrasill", "Yggdrasil", "イグドラシル"), ResearchSources.overview,
                "A host computer associated with its administered Digital World and Project Ark. It is not a universal name for every world administrator: Iliad has Homeros, and Shambhala has Kunlun.",
                "Um computador host ligado ao Mundo Digital que administra e ao Project Ark. Seu nome não designa todo administrador: Iliad possui Homeros e Shambhala possui Kunlun.",
                "管理するデジタルワールドとプロジェクトアークに関わるホストコンピューター。すべての世界の管理者の呼び名ではなく、イリアスはホメロス、シャンバラはコンロンが管理する。"),
            entry("Royal Knights", listOf("Royal Knights", "Cavaleiros Reais", "ロイヤルナイツ"), ResearchSources.profile(36, "Royal Knights"),
                "An order described as thirteen guardians at the highest level of network security in Yggdrasill's jurisdiction. They interpret orders individually and can disagree. Being the same species or form as a documented Knight does not automatically establish that individual's office.",
                "Uma ordem descrita como treze guardiões no nível mais alto da segurança da rede sob a jurisdição de Yggdrasill. Interpretam ordens individualmente e podem discordar. Ter a espécie ou forma de um Cavaleiro conhecido não concede automaticamente seu cargo a outro indivíduo.",
                "イグドラシルの管轄でネットワークセキュリティの最高位にある十三体とされる聖騎士集団。命令を各自で解釈し、対立もする。同じ種族・形態でも、その個体が役職を持つとは限らない。"),
            entry("Dark Area", listOf("Dark Area", "Área Sombria", "Cocytus", "ダークエリア", "コキュートス"), ResearchSources.profile(35, "Dark Areas and rebirth"),
                "Dark Areas exist in different Digital Worlds. The report describes Anubimon judging data, while Iliad's regional record describes Plutomon's role. Cocytus is a shared lowest region. Natural lifespan, violent death, and regional rebirth accounts should not be collapsed into one guaranteed outcome.",
                "Há Dark Areas em diferentes Mundos Digitais. O relatório descreve Anubimon julgando dados, enquanto o registro regional de Iliad descreve Plutomon. Cocytus é uma região inferior compartilhada. Fim da vida, morte violenta e renascimento regional não devem ser tratados como um único resultado garantido.",
                "各デジタルワールドにダークエリアがある。レポートはアヌビモンの判断を、イリアスの地域資料はプルートモンの役割を述べる。コキュートスは共通の最下層。寿命、戦闘での死、地域ごとの再生を一つの確定結果にしない。"),
            entry("X-Antibody", listOf("X-Antibody", "X Program", "X-Evolution", "X抗体", "Xプログラム"), ResearchSources.profile(27, "X Program and X-Antibody"),
                "X-Antibody counters X Program and can cause X-Evolution without changing the growth level. Some Digimon are born with it; acquired-antibody Digimon require continued intake according to this report. It is not a universal extra level or a memory of surviving Project Ark.",
                "X-Antibody combate X Program e pode causar X-Evolution sem mudar o nível de crescimento. Alguns Digimon nascem com ele; os que o adquirem precisam continuar a ingeri-lo, segundo este relatório. Não é um nível extra universal nem prova de ter vivido o Project Ark.",
                "X抗体はXプログラムに対抗し、同じ成長段階のままX進化を起こす。先天的に持つ個体もおり、後天的な個体には継続摂取が必要とされる。共通の追加レベルや、アークを生き延びた記憶ではない。"),
            entry("Ecological families", listOf("Nature Spirits", "Deep Savers", "Wind Guardians", "Metal Empire", "Nightmare Soldiers", "family", "família", "系統"), ResearchSources.profile(28, "Ecological families"),
                "Researchers group Digimon by habitat, type, and ecology into families such as Nature Spirits, Deep Savers, and Metal Empire. Families can overlap, and classification remains incomplete. A human-world map category is not proof of a species' published Digital World habitat.",
                "Pesquisadores agrupam Digimon por habitat, tipo e ecologia em famílias como Nature Spirits, Deep Savers e Metal Empire. As famílias podem se sobrepor, e a classificação permanece incompleta. Uma categoria do mapa humano não prova o habitat publicado de uma espécie no Mundo Digital.",
                "研究者は生息地、タイプ、生態からNATURE SPIRITS、DEEP SAVERS、METAL EMPIREなどに分類する。重なる系統もあり、分類は未完成。現実の地図分類だけで種族のデジタルワールドの生息地は確定しない。"),
            entry("Witchelny", listOf("Witchelny", "Witchmon", "Wizardmon", "Wizarmon", "ウィッチェルニー", "ウィザーモン"), ResearchSources.profile(32, "Witchelny and other layers"),
                "A distinct Digital World layer with four elemental peoples, governing sages, and a magic academy on Mount Brocken. Its magic includes advanced programming languages. Some graduates travel to other worlds; this does not give every member of a related species the same education or biography.",
                "Uma camada distinta do Mundo Digital, com quatro povos elementais, sábios governantes e uma academia de magia no Monte Brocken. Sua magia inclui linguagens avançadas de programação. Alguns formados viajam a outros mundos; isso não dá a todo indivíduo da espécie a mesma formação ou biografia.",
                "四つの元素の種族、賢者、ブロッケン山の魔法学園がある別レイヤーの世界。魔術には高級プログラム言語が含まれる。他世界へ旅立つ卒業生もいるが、同じ種族の全個体が同じ教育や来歴を持つわけではない。"),
            entry("Iliad", listOf("Iliad", "Ilias", "Homeros", "Homer", "Olympos XII", "イリアス", "ホメロス", "オリンポス十二神"), ResearchSources.iliad,
                "Iliad is a distinct world administered by Homeros and guarded by the Olympos XII. Separate layers developed their own ecologies after an ancient fragmentation account. Its Dark Area is ruled by Plutomon, returning functioning DigiCores as Digitama. Greek/Roman data influence is described as a research inference.",
                "Iliad é um mundo distinto administrado por Homeros e protegido pelos Olympos XII. Camadas separadas desenvolveram ecologias próprias após o relato de uma antiga fragmentação. Sua Dark Area é governada por Plutomon, que devolve DigiCores funcionais como Digitama. A influência de dados greco-romanos é uma inferência de pesquisa.",
                "イリアスはホメロスが管理し、オリンポス十二神が守護する独自の世界。古代の分断の伝承後、各層が独自に発展した。ダークエリアはプルートモンが支配し、正常なデジコアをデジタマとして還元する。ギリシャ・ローマのデータの影響は研究上の推察。", 12),
            entry("Shambhala", listOf("Shambhala", "Shambala", "Kunlun", "Konron", "Yomi", "シャンバラ", "コンロン", "黄泉"), ResearchSources.shambhala,
                "Shambhala is a distinct eastern Digital World administered by Kunlun. Genshi Continent, Ashino Island, and Yomi have their own ecologies and guardians. Susanoomon's rewriting is a transmitted creation account. Only a central part is observed; neither complete geography nor an individual's birthplace follows from a species name.",
                "Shambhala é um Mundo Digital oriental distinto, administrado por Kunlun. Genshi Continent, Ashino Island e Yomi têm ecologias e guardiões próprios. A reescrita por Susanoomon é uma tradição de criação. Apenas a região central foi observada; o nome de uma espécie não revela toda a geografia nem a origem de um indivíduo.",
                "シャンバラはコンロンが管理する東方の独自世界。ゲンシ大陸、アシノ島、黄泉には独自の生態系と守護者がある。スサノオモンの書き換えは創世の伝承。観測は中心部に限られ、種族名から全地理や個体の出身は分からない。", 12),
            entry("Digimon Dock and Mindlink", listOf("Digimon Dock", "Digimon Linker", "Mindlink", "Mind Link", "デジモンドック", "マインドリンク"), ResearchSources.seekers,
                "In Seekers' technical records, a Digimon Dock stores Digimon. The Digimon Linker is a particular smartwatch-type Dock; Mindlink transfers a user's digitized consciousness into a DigiCore. This is specific technology, not another name for an ordinary NFC transfer or all wearable devices.",
                "Nos registros técnicos de Seekers, um Digimon Dock armazena Digimon. Digimon Linker é um modelo específico em forma de relógio; Mindlink transfere a consciência digitalizada do usuário para um DigiCore. É uma tecnologia específica, não outro nome para NFC ou para todo dispositivo vestível.",
                "Seekersの技術記録ではデジモンドックがデジモンを保存する。デジモンリンカーは特定の時計型ドックで、マインドリンクは精神をデジコアへ転送する技術。通常のNFC転送やすべての腕時計端末と同一ではない。"),
            entry("Observed visualization", listOf("Holoize", "Holorize", "projection", "visualization", "projeção", "ホロライズ"), ResearchSources.seekersResearch,
                "Ryusenji distinguishes a world visualization generated from observations from directly perceiving the Digital World. A device's displayed representation is a view of data; it does not by itself establish physical manifestation, direct sensation, or an individual's memory of visiting the depicted location.",
                "Ryusenji distingue uma visualização gerada a partir de observações da percepção direta do Mundo Digital. A imagem exibida por um dispositivo representa dados; por si só não prova manifestação física, sensação direta ou lembrança de visitar o lugar mostrado.",
                "龍泉寺は観測データから生成した世界の可視化と、直接世界を感じることを区別する。端末の表示だけで物理的な出現、直接の感覚、その場所を訪れた記憶が確定するわけではない。"),
            entry("Re:Digitize storage", listOf("Re:Digitize", "Re Digitize", "DigiStorage", "GIGO", "リデジタイズ", "デジストレージ"), ResearchSources.redigitizeStorage,
                "Re:Digitize records a digital world distinct from human reality. DigiStorage can register a developing partner's data and Digimon recorded on storage cards. Storage records and Colosseum mechanics belong to that technical context; they do not establish universal reproduction or evolution rules.",
                "Re:Digitize registra um mundo digital distinto da realidade humana. DigiStorage registra os dados de um parceiro em desenvolvimento e Digimon de cartões de armazenamento. Esses registros e as regras do Colosseum pertencem a esse contexto técnico; não são regras universais de reprodução ou evolução.",
                "Re:Digitizeは人間の現実とは別のデータ世界を記録する。デジストレージには育成中のパートナーやストレージカードのデータを登録できる。保存やコロシアムの仕組みはその技術的文脈に属し、共通の繁殖・進化規則ではない。"),
            entry("D-Storage", listOf("D-Storage", "D Storage", "Liberator", "リベレイター"), ResearchSources.liberator,
                "Liberator's D-Storage combines a library, communications, partner registration and summoning, event notices, and battle/tournament records. Its real-world deck-case functions and Lacuna functions differ. These are specific capabilities of that device and context.",
                "D-Storage, em Liberator, reúne biblioteca, comunicação, registro e convocação de parceiros, avisos de eventos e registros de batalhas e torneios. As funções físicas de porta-deck e as funções em Lacuna são distintas. São capacidades específicas desse dispositivo e contexto.",
                "LiberatorのD-Storageはライブラリー、通信、パートナー登録と召喚、イベント通知、バトル・大会記録を備える。現実のデッキケース機能とラクーナの機能は異なり、その端末と文脈に固有の能力である。"),
            entry("Lacuna and the Garden", listOf("Lacuna", "Garden", "cardification", "ラクーナ", "ガーデン"), ResearchSources.liberatorGarden,
                "The Garden conservation report describes real digital life discovered in the cyberspace used for Lacuna, separately from manufactured NPCs. The Garden is a self-contained conservation domain; cardification helps Digimon persist and adapt to Lacuna. Origins and some wild survival mechanisms remain unknown.",
                "O relatório de conservação do Garden descreve vida digital real descoberta no espaço usado para Lacuna, distinta dos NPCs fabricados. O Garden é um domínio autônomo de conservação; a cardificação ajuda Digimon a persistir e se adaptar a Lacuna. A origem e alguns mecanismos de sobrevivência selvagem permanecem desconhecidos.",
                "ガーデンの保護報告は、ラクーナの基礎となる電脳空間で見つかった実在のデジタル生命と人工NPCを区別する。ガーデンは独立した保護領域で、カード化はラクーナへの定着と適応を助ける。起源や一部の野生の生存機構は不明。"),
            entry("Vital Bracelet", listOf("Vital Bracelet", "VB", "Watch", "relógio", "バイタルブレス"), ResearchSources.deviceHistory,
                "Vital Bracelet models link heart-rate and activity readings to development and use DiM/BEM data. These are model-specific device functions. Recorded readings can describe this partner's condition, but they do not invent past events or imply Mindlink capability.",
                "Modelos de Vital Bracelet relacionam leituras de atividade e frequência cardíaca ao desenvolvimento e usam dados DiM/BEM. São funções específicas do dispositivo. As leituras descrevem a condição do parceiro, mas não inventam acontecimentos passados nem implicam capacidade de Mindlink.",
                "バイタルブレスは活動や心拍の情報を成長に結びつけ、DiM・BEMデータを使用する。機種固有の機能であり、記録は状態の参考となるが、過去の出来事やマインドリンク能力を作らない。"),
            entry("Tamer", listOf("Tamer", "テイマー", "Chosen Child", "DigiDestined", "Digiescolhido"), ResearchSources.deviceHistory,
                "A Tamer is a human who works with or partners a Digimon. Chosen Children are a particular role, not a universal synonym. Device types and sources describe different partnerships; personal closeness must come from this individual's actual relationship and recorded encounters.",
                "Tamer é um humano que trabalha com um Digimon ou forma parceria com ele. Digiescolhidos são um papel específico, não um sinônimo universal. Fontes e dispositivos descrevem parcerias diferentes; a proximidade pessoal vem da relação e dos encontros registrados deste indivíduo.",
                "テイマーはデジモンと活動したりパートナーとなる人間。選ばれし子供は特定の役割で、全テイマーの同義語ではない。端末や資料により関係は異なり、親しさはこの個体の実際の関係と交流の記録から判断する。")
        )
    }
}
